parameters.jsCode:
// Segunda rama del mismo Webhook: el informe COMPLETO, pero al email del
// propio lead (no al negocio) — cumple la promesa "Te enviaremos tu
// informe completo a este email" del formulario. Solo texto, sin
// adjuntar fotos (el nodo Gmail no lleva attachmentsUi).
//
// Si no hay email (cliente sin ese campo activo en cta.campos), no se
// devuelve ningún item: el nodo Gmail de esta rama simplemente no se
// ejecuta para esa ejecución, en vez de fallar por "sendTo" vacío.

const body = $input.first().json.body || $input.first().json;
if (!body.email) return [];

function formatearBloque(b) {
  switch (b.tipo) {
    case 'puntuaciones':
      return 'Puntuación por zonas:\n' + (b.items || [])
        .map((i) => `  - ${i.nombre}: ${i.puntuacion}/100 — ${i.observacion}`)
        .join('\n');
    case 'fortalezas':
      return 'Fortalezas:\n' + (b.items || []).map((i) => `  - ${i}`).join('\n');
    case 'recomendaciones':
      return 'Recomendaciones:\n' + (b.items || [])
        .map((r) => `  - ${r.titulo} (${r.zona}): ${r.beneficio}${r.detalle ? '. ' + r.detalle : ''}`)
        .join('\n');
    case 'checklist':
      return 'Checklist:\n' + (b.items || [])
        .map((c) => `  - [${c.estado}] ${c.nombre}${c.observacion ? ': ' + c.observacion : ''}`)
        .join('\n');
    case 'propuesta':
      return 'Propuesta:\n' + (b.partidas || [])
        .map((p) => `  - ${p.nombre}: ${p.descripcion}`)
        .join('\n');
    case 'horquilla_precio': {
      const rango = `${b.minimo}–${b.maximo} ${b.moneda || ''}`.trim();
      return `Rango de precio orientativo: ${rango}${b.nota ? ' (' + b.nota + ')' : ''}`;
    }
    default:
      return null;
  }
}

const bloques = Array.isArray(body.bloques) ? body.bloques : [];
const bloques_texto = bloques
  .filter((b) => b.tipo !== 'imagen_despues')
  .map(formatearBloque)
  .filter(Boolean)
  .join('\n\n') || '(sin bloques en el informe)';

return [{
  json: {
    nombre: body.nombre || '',
    email: body.email,
    resumen: body.resumen || '',
    bloques_texto,
  },
}];

